local lfs = require("lfs")

if lfs.attributes("/etc/config/mmpbx", "mode") ~= "file" then
  return
end

local tonumber, tostring, ipairs, setmetatable =
      tonumber, tostring, ipairs, setmetatable
local format, match = string.format, string.match
local ucihelper = mapper("ucihelper")
local generate_key_on_uci = ucihelper.generate_key_on_uci
local foreach_on_uci = ucihelper.foreach_on_uci

local InternetGatewayDevice_Services_VoiceService_i_Capabilities_Codecs_i_ = {
    objectType = {
        name = "InternetGatewayDevice.Services.VoiceService.{i}.Capabilities.Codecs.{i}.",
        access = "readOnly",
        minEntries = 0,
        maxEntries = math.huge,
        parameters = {
            EntryID = {
                access = "readOnly",
                activeNotify = "canDeny",
                type = "unsignedInt",
                range = {
                    {
                        min = "1",
                    },
                },
            },
            Codec = {
                access = "readOnly",
                activeNotify = "canDeny",
                type = "string",
                max = "64",
                enumeration = {
                    "G.711MuLaw",
                    "G.711ALaw",
                    "G.726",
                    "G.729",
                    "G.729a",
                    "G.729e",
                    "G.728",
                    "G.723.1",
                    "G.722",
                    "G.722.1",
                    "G.722.2",
                    "GSM-FR",
                    "GSM-HR",
                    "GSM-EFR",
                    "iLBC",
                },
            },
            BitRate = {
                access = "readOnly",
                activeNotify = "canDeny",
                type = "unsignedInt",
            },
            ----      PacketizationPeriod = {
            ----        access = "readOnly",
            ----        activeNotify = "canDeny",
            ----        list = true,
            ----        type = "string",
            ----        max = "64",
            ----      },
            SilenceSuppression = {
                access = "readOnly",
                activeNotify = "canDeny",
                type = "boolean",
            },
        }
    }
}

local mt = { __index = function() return "" end }
local codec_rates = setmetatable({
    PCMU = "64000",
    PCMA = "64000",
    G722 = "64000",
    ["G726-16"] = "16000",
    ["G726-24"] = "24000",
    ["G726-32"] = "32000",
    ["G726-40"] = "40000",
    G729 = "8000",
    G723 = "6300"
}, mt)

local codec_binding = { config = "mmpbx", sectionname = "codec_filter" }
local content_codecs = {}

InternetGatewayDevice_Services_VoiceService_i_Capabilities_Codecs_i_.entries = function(mapping, parentkey)
    local entries = {}
    local codecs = {}
    local missing_ID = {}
    local max_ID = 0
    -- there can be multiple codec filters with the same name (internal and
    -- sip have their own set of codecs) but here we should report each
    -- codec only once
    local res = foreach_on_uci(codec_binding, function(s)
        -- We need to be backwards compatible: key generation has been updated
        -- to store entryID as _key but the new code has to be able to deal with
        -- the old _key and _entryID fields.
        -- First check if there's a _entryID field and if so assume the old
        -- way of working.
        local entryID = s._entryID or s._key
        if not entryID then
            missing_ID[#missing_ID + 1] = s
        else
            local ID = tonumber(entryID)
            if ID > max_ID then
                max_ID = ID
            end
            local name = s.name
            if not codecs[name] then
                entries[#entries + 1] = format("%s|%s", s._key, parentkey)
                content_codecs[s._key] = name
                -- For backwards compatibility we also need to cache the entryID.
                -- Note that s._entryID is nil when keys were generated by the
                -- new code so the cache is not larger than strictly necessary.
                content_codecs[name] = s._entryID
                codecs[name] = true
            end
        end
    end)
    if #missing_ID > 0 then
        local binding = { config = "mmpbx" }
        for _, s in ipairs(missing_ID) do
            max_ID = max_ID + 1
            local entryID = tostring(max_ID)
            binding.sectionname = s[".name"]
            generate_key_on_uci(binding, entryID)
            local name = s.name
            if not codecs[name] then
                entries[#entries + 1] = format("%s|%s", entryID, parentkey)
                content_codecs[entryID] = name
                codecs[name] = true
            end
        end
        ucihelper.commit_keys(binding)
    end
    return entries
end

InternetGatewayDevice_Services_VoiceService_i_Capabilities_Codecs_i_.getall = function(mapping, key)
    local id = match(key, "^(.*)|")
    local name = content_codecs[id]
    return {
        EntryID = content_codecs[name] or id,  -- backwards compatibility; see entries()
        Codec = name,
        BitRate = codec_rates[name],
        SilenceSuppression = "1"
    }
end

InternetGatewayDevice_Services_VoiceService_i_Capabilities_Codecs_i_.get = {
    EntryID = function(mapping, paramname, key)
        local id = match(key, "^(.*)|")
        return content_codecs[content_codecs[id]] or id  -- backwards compatibility; see entries()
    end,
    Codec = function(mapping, paramname, key)
        local id = match(key, "^(.*)|")
        return content_codecs[id]
    end,
    BitRate = function(mapping, paramname, key)
        local id = match(key, "^(.*)|")
        return codec_rates[content_codecs[id]]
    end,
    SilenceSuppression = "1"
}

register(InternetGatewayDevice_Services_VoiceService_i_Capabilities_Codecs_i_)
